//! `bsc session ask` (#architect-asks-a-system-session-for-a-service) — a DELIVERY, not a conversation.
//!
//! ## The verb the epic says is the common case
//! Start and stop are lifecycle. Requesting is what the architect actually does most: it asks the
//! designer for a kit or the librarian for an implementation, without owning that session's lifecycle.
//! Collapsing the three into "the architect can spin up sessions" would make every request a lifecycle
//! event and leave the architect owning a fleet of studios it wanted one thing from.
//!
//! ## THE LOOP IS BACK, and the measurement is why it left and why it returned
//!
//! This verb used to open a `bsc_loop`, and the loop was removed on hard evidence: 20 ask loops, 0
//! turns. That evidence was real and the diagnosis was wrong. The loop's TRANSPORT was `bsc loop
//! watch` — a blocking read the callee had to volunteer into — and it never volunteered. Everything
//! else the loop gave was fine and unused: a durable record, strict turn alternation, an `--until`
//! signal, a turn ceiling, a budget. The three loops that DID work (21 turns) were the overnight
//! designer pump, where an app-side driver ACTUATES instead of waiting to be joined.
//!
//! So the two halves were never wrong; they were never connected. Delivery became reliable in between
//! — start-with, inject, interrupt, wait-for-idle, and an Enter that actually submits, five separate
//! defects — and that is the transport the loop always needed.
//!
//! **A turn is DELIVERED, never watched.** `ask` opens the loop and pushes turn one;
//! [`crate::reply`] posts a turn and pushes it to the other participant. Nobody blocks and nobody
//! polls. `bsc loop watch` is untouched and remains the designer pump's rendezvous, which wants one.
//!
//! ## Why it does not wait for the answer
//!
//! Because it does not have to any more: the reply is pushed to the caller. A verb that blocks is the
//! failure a whole day went into removing — a director sat for five minutes on an idle that could
//! never come. `ask` returns the loop id; the answer arrives on its own.
//!
//! ## The three states, which are the whole verb
//!
//! | target state | what happens |
//! |---|---|
//! | stopped | started with the REQUEST as its launch prompt |
//! | idle | the request written straight to its prompt |
//! | working | [`BusyPolicy`] decides: stand off, wait for idle, or interrupt |

pub use resolve_askable::resolve_askable;
pub use loop_prompt::loop_prompt;
pub use reply::reply;
pub use reply_prompt::reply_prompt;

use crate::deliver::Action;
use std::time::{Duration, Instant};

/// The architect's participant name, and the fallback caller for a bare CLI run.
///
/// It was ALSO, until `session-ask-assumes-its-caller-is-always-the-architect`, hard-coded as *the*
/// caller — the verb was written for one caller and grew a second. A director running
/// `bsc session ask architect …` was refused with "it is the caller of this verb", which is a true
/// statement about the architect and a false one about the director doing the asking.
pub const ARCHITECT_PARTICIPANT: &str = "architect";

/// Who is asking.
///
/// Read from `$BSC_AUDIT_PANE`, the pane id every session already carries. A pane that IS a system
/// session resolves to that session's short id, so the architect keeps calling itself `architect`;
/// anything else — a project director, a worker — uses its pane id, which is already unique per
/// session.
///
/// Falls back to the architect when the variable is absent, which is a bare CLI run outside any
/// session and is exactly what the verb assumed before.
pub fn caller_participant() -> String {
    let pane = std::env::var("BSC_AUDIT_PANE").unwrap_or_default();
    let pane = pane.trim();
    if pane.is_empty() || pane == "?" {
        return ARCHITECT_PARTICIPANT.to_string();
    }
    // Derived from the pane grammar rather than looked up in a table, since
    // `the-studio-session-set-is-derived-not-declared`. Same answer for every session that existed
    // before, and it now also names a studio whose technology arrived after this binary was built —
    // which the table could not, so such a caller was reported by its raw pane id.
    crate::session_id_for_pane(pane).unwrap_or_else(|| pane.to_string())
}

/// How long a `--on-busy wait` ask will wait for its target to go idle before giving up.
///
/// This used to bound the ANSWER, back when there was one to wait for. It now bounds the only wait
/// the verb still has, and the name it is spelled with (`--wait`) is unchanged.
pub const DEFAULT_IDLE_WAIT_SECS: u64 = 300;

/// What an ask does when its target is WORKING — one axis, three values.
///
/// The maintainer named two of these as things the verb should be able to do
/// (#an-ask-to-a-working-session-has-two-ways-through): "send a request that waits until the session
/// is idle, or send a request and force it into the session even if it's working". The third is what
/// the verb already did, and it stays the DEFAULT — an ask must not disturb work in progress because
/// the caller forgot a flag.
///
/// One enum rather than two booleans because the values are mutually exclusive: `--wait --interrupt`
/// as a pair of flags has an obvious spelling and no obvious meaning, and whichever precedence you
/// pick, half the callers guess the other one.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum BusyPolicy {
    /// Leave the working session alone; report that nothing was delivered. The default.
    #[default]
    Leave,
    /// Wait for it to go idle, then deliver. The waiting happens HERE rather than in the app — see
    /// [`ask`] for why re-measuring is the point.
    Wait,
    /// Cut into the turn in flight and deliver now.
    Interrupt,
}

impl BusyPolicy {
    /// Parse the `--on-busy` value. The error names the whole set, because the realistic mistake is a
    /// near-miss (`queue`, `idle`) and a caller told only "invalid" just guesses again.
    pub fn parse(v: &str) -> Result<Self, String> {
        match v {
            "leave" => Ok(Self::Leave),
            "wait" => Ok(Self::Wait),
            "interrupt" => Ok(Self::Interrupt),
            other => Err(format!(
                "--on-busy: '{other}' is not a busy policy. Valid values: leave · wait · interrupt.\n\
                 leave (the default) stands off and tells you; wait polls until the session is idle \
                 and then delivers; interrupt cuts into the turn in flight."
            )),
        }
    }

    /// What reaches the APP as `DeliverRequest.interrupt`.
    ///
    /// `Wait` sends FALSE, and that is the whole reason the wait can live in the CLI: each poll is an
    /// ordinary non-interrupting delivery, so a target that has gone idle is simply Injected by the
    /// route that already exists. Sending true would cut in on the first poll, which is the other
    /// policy.
    pub fn interrupts(self) -> bool {
        matches!(self, Self::Interrupt)
    }
}

/// How often a `--on-busy wait` ask re-measures its target.
///
/// Each of these is an appchan round trip to the app, and a session that is working is working for
/// turns, not for milliseconds — a tighter interval would buy nothing and bill the app for it.
pub const BUSY_POLL_MS: u64 = 3_000;

/// What `ask` produced.
///
/// There is no `answer` field: this verb does not wait for one. What the caller gets is the LOOP the
/// exchange runs in and WHICH ROUTE the request took to reach the session. The answer arrives later,
/// delivered, and can be read from the loop whenever the caller wants it.
#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AskResult {
    pub id: String,
    /// The LOOP this ask opened (#an-ask-is-a-loop-again-and-every-turn-is-delivered).
    ///
    /// Printed on every path, because it is how the exchange is continued and read. The verb does not
    /// block on an answer — a reply is DELIVERED to the caller when it comes — so this id is what the
    /// caller keeps, rather than a turn it sat waiting for.
    pub loop_id: i64,
    /// WHICH route the request took to reach the session — started with it, injected at its idle
    /// prompt, interrupted with it, or not delivered because it was working and the caller stood off.
    pub delivery: Action,
    /// How long this ask spent waiting for a WORKING target to go idle, when it waited at all.
    ///
    /// Present only under [`BusyPolicy::Wait`], and reported because it is the one thing that
    /// separates a request that took a while to LAND from one that landed at once.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub waited_ms: Option<u64>,
}

impl AskResult {
    /// Whether the request actually reached the session. False for exactly one case — a working
    /// target the caller chose to stand off from — and that case is why this is not implicit.
    pub fn delivered(&self) -> bool {
        self.delivery != Action::LeaveWorking
    }
}

/// Everything `ask` needs from the outside world, injected so the decision logic is testable without
/// a running app.
pub trait AskEnv {
    /// Put the request in front of the session, whatever state it is in, and say which route was
    /// taken (#an-ask-is-delivered-not-left-to-be-found).
    ///
    /// The decision lives in the APP because the app is what can measure the target; this side's job
    /// is to choose the policy and report what happened.
    fn deliver(&self, session_id: &str, request: &str, interrupt: bool) -> Result<Action, String>;
    /// Open the loop this ask runs in; returns its id.
    ///
    /// The SESSION is participant `a` and the caller is `b`, because `a` speaks first and the seed is
    /// what `a` replies to. Backwards, the caller would be answering its own question.
    fn open_loop(&self, session_id: &str, request: &str, caller: &str) -> Result<i64, String>;
    /// How long to sleep between re-measurements while waiting out a WORKING target.
    ///
    /// A provided method with the real interval, overridden only by the test fake. The alternative —
    /// a constant read inside [`ask`] — makes the wait loop cost three real seconds per poll to
    /// exercise, so the only affordable test is the one that proves waiting GIVES UP. The case that
    /// matters is the one where it gets through.
    fn busy_poll(&self) -> Duration {
        Duration::from_millis(BUSY_POLL_MS)
    }
}

/// Put a request in front of a system session.
///
/// # The idle wait lives HERE, not in the app
///
/// Under [`BusyPolicy::Wait`] this polls [`AskEnv::deliver`] and RE-MEASURES on every poll, rather
/// than asking the app to hold one request open until the target frees up. Three reasons, and the
/// third is the one that would have caused a bug:
///
///  - A round trip sized in SECONDS (`--timeout`, default 8s) cannot carry a wait measured in turns.
///  - The app would decide once, from a probe taken before the wait began — so a target that stopped
///    while we waited would still be treated as live.
///  - Re-measuring means every poll goes through `deliver::plan` again, so the OTHER routes compose
///    for free: a target that goes idle is Injected, one that has stopped is started WITH the
///    request, and neither needs a case of its own here.
pub fn ask(
    env: &dyn AskEnv,
    session_id: &str,
    request: &str,
    // How long to keep waiting for a busy target. Only consulted under `BusyPolicy::Wait`.
    idle_wait: Duration,
    // Who is asking. Threaded rather than read here so the decision logic stays testable without an
    // environment — the same reason `AskEnv` exists.
    caller: &str,
    // What to do when the target is WORKING. `Leave` by default: an ask must not disturb work in
    // progress because the caller forgot a flag.
    on_busy: BusyPolicy,
) -> Result<AskResult, String> {
    let session = resolve_askable(session_id, caller)?;
    let request = request.trim();
    if request.is_empty() {
        return Err(format!("usage: bsc session ask {} \"<request>\"", session.id));
    }

    // ORDER IS LOAD-BEARING: the loop is opened BEFORE the request is delivered, so its id exists to
    // ride into the launch prompt of a session that has to be STARTED. Otherwise a woken session comes
    // up holding a request with no way to answer it.
    let loop_id = env.open_loop(&session.id, request, caller)?;
    let carried = loop_prompt(loop_id, &session.id, request);

    // DELIVER it. The app measures the target and routes: a stopped session is woken holding the
    // request, an idle one is handed it, a working one is left alone unless we asked to cut in.
    let mut delivery = env.deliver(&session.id, &carried, on_busy.interrupts())?;
    let mut waited_ms = None;

    // WAIT FOR IDLE. Each pass is a fresh measurement, so this exits the moment the target reaches any
    // state that can take the request — idle, or stopped and startable.
    if delivery == Action::LeaveWorking && on_busy == BusyPolicy::Wait {
        let started = Instant::now();
        let deadline = started + idle_wait;
        while delivery == Action::LeaveWorking && Instant::now() < deadline {
            std::thread::sleep(env.busy_poll());
            delivery = env.deliver(&session.id, &carried, false)?;
        }
        waited_ms = Some(started.elapsed().as_millis() as u64);
    }

    Ok(AskResult { id: session.id.to_string(), loop_id, delivery, waited_ms })
}

/// The sentinel a participant appends to close an ask loop.
///
/// A request wants an END, not an open conversation: without a signal the loop sits open after the work
/// is done and `bsc loop list` fills with resolved exchanges that look pending.
pub const ANSWER_SIGNAL: &str = "ANSWERED";

/// An ask loop is a question, an answer, and room for a clarification or two — not a conversation. The
/// ceiling is what stops a pair of agents talking to each other indefinitely.
pub const ASK_MAX_TURNS: i64 = 6;

/// The appchan round trip. Separated from the pure decision above so the wait logic is testable
/// without a running app.
pub struct ChannelEnv {
    pub timeout_ms: i64,
}

impl ChannelEnv {
    /// The loop store, located the way every other `bsc` store is.
    pub(crate) fn loop_store() -> Result<bsc_loop::Store, String> {
        let path = bsc_sqlite_util::default_store_path("BSC_LOOP_DB", &["loops.db"])
            .ok_or("cannot locate loops.db — set $BSC_LOOP_DB")?;
        bsc_loop::Store::open(&path).map_err(|e| format!("opening the loop store: {e}"))
    }
}

impl AskEnv for ChannelEnv {
    fn open_loop(&self, session_id: &str, request: &str, caller: &str) -> Result<i64, String> {
        let lp = Self::loop_store()?
            .create(
                &bsc_loop::NewLoop {
                    // The SESSION is `a`: it speaks first, replying to the seed, which IS the request.
                    a: session_id.to_string(),
                    b: caller.to_string(),
                    seed: request.to_string(),
                    until: Some(ANSWER_SIGNAL.to_string()),
                    max_turns: Some(ASK_MAX_TURNS),
                    budget: None,
                    project: None,
                },
                bsc_util::now_ms(),
            )
            .map_err(|e| format!("opening the loop: {e}"))?;
        Ok(lp.id)
    }

    fn deliver(&self, session_id: &str, request: &str, interrupt: bool) -> Result<Action, String> {
        // One round trip. The app holds the probe (`live` + the agent-level `working`), so it — not
        // this CLI — is what can decide between waking, injecting and standing off.
        let req = crate::DeliverRequest {
            id: session_id.to_string(),
            text: request.to_string(),
            interrupt,
        };
        let res: crate::DeliverResult = crate::cli::ask(crate::DELIVER_KIND, &req, self.timeout_ms)?;
        Ok(res.action)
    }
}

/// What a [`reply`] did — never silent, for the same reason a delivery is never silent.
#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ReplyResult {
    pub loop_id: i64,
    /// The turn number this posted.
    pub seq: i64,
    /// Set when this turn ENDED the loop — the signal, the ceiling, or the budget.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub closed: Option<String>,
    /// Who the turn was delivered to, and by which route. `None` when the other participant is not a
    /// system session this verb can reach — the overnight designer pump's `driver`, or a director whose
    /// pane is not in the registry. That is a REPORTED no-op, not a failure: the turn is posted and
    /// durable either way, and pretending otherwise would make the pump's every turn an error.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub delivered_to: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub delivery: Option<Action>,
}

/// One posted turn, as [`reply`] needs it back.
#[derive(Debug, Clone, PartialEq)]
pub struct Posted {
    pub seq: i64,
    pub closed: Option<String>,
}

/// Everything [`reply`] needs from the outside world, injected so the decision is testable without a
/// store or a running app.
pub trait ReplyEnv {
    /// The loop's two participants, in `(a, b)` order.
    fn participants(&self, loop_id: i64) -> Result<(String, String), String>;
    /// Post the turn. The store refuses one that is not this speaker's, or one into a closed loop.
    fn say(&self, loop_id: i64, speaker: &str, text: &str) -> Result<Posted, String>;
    /// Put the turn in front of the other participant, by the same routing an ask uses.
    fn deliver(&self, session_id: &str, text: &str) -> Result<Action, String>;
}

impl ReplyEnv for ChannelEnv {
    fn participants(&self, loop_id: i64) -> Result<(String, String), String> {
        let lp = Self::loop_store()?
            .get(loop_id)
            .map_err(|e| format!("reading the loop: {e}"))?
            .ok_or_else(|| format!("no loop {loop_id} — `bsc loop list` shows the open ones"))?;
        Ok((lp.a, lp.b))
    }

    fn say(&self, loop_id: i64, speaker: &str, text: &str) -> Result<Posted, String> {
        let out = Self::loop_store()?
            .say(
                loop_id,
                speaker,
                &bsc_loop::SayInput {
                    message: text.to_string(),
                    shot_path: None,
                    tokens: 0,
                    cost: 0.0,
                    ts: bsc_util::now_ms(),
                },
            )
            .map_err(|e| format!("posting the turn: {e:?}"))?;
        Ok(Posted { seq: out.seq, closed: out.closed })
    }

    fn deliver(&self, session_id: &str, text: &str) -> Result<Action, String> {
        // A reply never interrupts: the recipient asked for this exchange, and cutting into whatever it
        // is doing to hand it an answer it will read anyway is the rudest possible reading of "reply".
        AskEnv::deliver(self, session_id, text, false)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::RefCell;

    struct Fake {
        live: bool,
        /// Whether the target's AGENT is running something — what routes idle vs working.
        working: bool,
        /// How many deliveries the target stays WORKING for before it frees up. `None` ⇒ forever.
        ///
        /// This is what makes the wait loop testable: a fixed `working` can only prove that waiting
        /// gives up, never that it gets through. Counting deliveries reproduces the real sequence —
        /// busy, busy, then idle — without a clock.
        busy_for: Option<usize>,
        /// Whether the target STOPS once it stops being busy — the case that proves the wait
        /// re-measures rather than assuming the target is still live.
        stops_when_free: bool,
        /// Every delivery, as (session, request, interrupt-requested).
        delivered: RefCell<Vec<(String, String, bool)>>,
        /// Every loop opened, as (session, request, caller).
        opened: RefCell<Vec<(String, String, String)>>,
    }

    impl Fake {
        fn new(live: bool) -> Self {
            Self {
                live,
                working: false,
                busy_for: None,
                stops_when_free: false,
                delivered: RefCell::new(vec![]),
                opened: RefCell::new(vec![]),
            }
        }
    }

    impl AskEnv for Fake {
        fn open_loop(&self, s: &str, r: &str, caller: &str) -> Result<i64, String> {
            self.opened.borrow_mut().push((s.into(), r.into(), caller.into()));
            Ok(77)
        }
        fn deliver(&self, s: &str, r: &str, interrupt: bool) -> Result<Action, String> {
            let n = self.delivered.borrow().len();
            self.delivered.borrow_mut().push((s.into(), r.into(), interrupt));
            // The target frees up after `busy_for` deliveries — and MAY have stopped by then, which is
            // the case that catches a wait loop assuming its target is still live.
            let still_busy = self.working && self.busy_for.is_none_or(|k| n < k);
            let live = if self.working && !still_busy && self.stops_when_free { false } else { self.live };
            // The same routing the app performs, so the CLI-side decisions are exercised against the
            // real policy rather than a second copy of it.
            Ok(crate::deliver::plan(live, still_busy, interrupt))
        }
        // Fast enough that a multi-poll wait is a unit test rather than a nine-second one.
        fn busy_poll(&self) -> Duration {
            Duration::from_millis(5)
        }
    }

    const T: Duration = Duration::from_millis(400);

    #[test]
    fn a_stopped_session_is_started_with_the_request_itself() {
        // THE COLD START, and the reason the loop could go. The session is born holding the request,
        // so there is nothing for it to look up and nothing it has to opt into.
        let f = Fake::new(false);
        let r = ask(&f, "librarianRust", "implement dijkstra in rust", T, ARCHITECT_PARTICIPANT, BusyPolicy::Leave).unwrap();
        assert_eq!(r.delivery, Action::StartWith);
        assert!(r.delivered());
        let d = f.delivered.borrow();
        assert_eq!(d.len(), 1);
        assert_eq!(d[0].0, "librarianRust");
        assert!(d[0].1.starts_with("implement dijkstra in rust"),
            "the REQUEST leads — not a pointer to somewhere it can be found: {}", d[0].1);
        assert!(d[0].1.contains("bsc session reply 77"),
            "…and the way to answer travels WITH it: {}", d[0].1);
        assert_eq!(f.opened.borrow()[0].0, "librarianRust", "the SESSION is participant a");
    }

    #[test]
    fn an_idle_session_is_handed_the_request_without_being_restarted() {
        // Asking must not touch lifecycle: that is what makes this a request and not a launch.
        let f = Fake::new(true);
        let r = ask(&f, "designerReact", "make me a card", T, ARCHITECT_PARTICIPANT, BusyPolicy::Leave).unwrap();
        assert_eq!(r.delivery, Action::Inject);
        assert_eq!(f.delivered.borrow().len(), 1, "delivered exactly once");
    }

    #[test]
    fn the_request_is_trimmed_but_otherwise_delivered_verbatim() {
        let f = Fake::new(true);
        ask(&f, "designerReact", "  make me a card  ", T, ARCHITECT_PARTICIPANT, BusyPolicy::Leave).unwrap();
        assert!(f.delivered.borrow()[0].1.starts_with("make me a card\n"));
        assert_eq!(f.opened.borrow()[0].1, "make me a card", "trimmed, and the seed verbatim");
    }

    #[test]
    fn a_working_session_is_left_alone_by_default_and_the_caller_is_told_at_once() {
        let f = Fake { working: true, ..Fake::new(true) };
        let started = Instant::now();
        let r = ask(&f, "designerReact", "q", Duration::from_secs(30), ARCHITECT_PARTICIPANT, BusyPolicy::Leave).unwrap();
        assert_eq!(r.delivery, Action::LeaveWorking);
        assert!(!r.delivered(), "nothing reached the session, and that is the one case where that is true");
        assert!(r.waited_ms.is_none(), "it did not wait, so it must not claim to have");
        assert!(started.elapsed() < Duration::from_secs(1), "leave is the default — it must never block");
        assert_eq!(f.delivered.borrow().len(), 1, "one measurement, no polling");
    }

    #[test]
    fn a_working_session_is_cut_into_when_the_caller_asks_for_it() {
        let f = Fake { working: true, ..Fake::new(true) };
        let r = ask(&f, "designerReact", "q", T, ARCHITECT_PARTICIPANT, BusyPolicy::Interrupt).unwrap();
        assert_eq!(r.delivery, Action::InterruptWith);
        // The interrupt REQUEST is what reached the app — the CLI does not decide to interrupt on its
        // own, it passes the caller's policy through.
        assert!(f.delivered.borrow()[0].2, "the interrupt flag is carried, not invented");
    }

    #[test]
    fn a_working_session_is_waited_out_and_then_delivered_to() {
        // The route that did not exist before `--on-busy`: a caller who needs the request to LAND but
        // will not cut into work in flight.
        let f = Fake { working: true, busy_for: Some(3), ..Fake::new(true) };
        let r = ask(&f, "designerReact", "q", Duration::from_secs(30), ARCHITECT_PARTICIPANT, BusyPolicy::Wait).unwrap();
        assert_eq!(r.delivery, Action::Inject, "it lands by the ordinary idle route once the target frees up");
        assert!(r.delivered());
        assert_eq!(f.delivered.borrow().len(), 4, "three measurements found it busy, the fourth delivered");
        assert!(
            f.delivered.borrow().iter().all(|(_, _, interrupt)| !interrupt),
            "waiting NEVER cuts in — that is the other policy, and sending true would make them the same",
        );
        assert!(r.waited_ms.is_some(), "the wait is reported");
    }

    #[test]
    fn a_target_that_stops_while_we_wait_is_started_with_the_request() {
        // The reason the wait RE-MEASURES instead of deciding once. A target can free up by exiting,
        // and a loop that assumed "still live, now idle" would inject into a PTY that is gone.
        let f = Fake { working: true, busy_for: Some(2), stops_when_free: true, ..Fake::new(true) };
        let r = ask(&f, "designerReact", "q", Duration::from_secs(30), ARCHITECT_PARTICIPANT, BusyPolicy::Wait).unwrap();
        assert_eq!(r.delivery, Action::StartWith, "woken holding the request, not injected into nothing");
    }

    #[test]
    fn a_wait_that_runs_out_of_budget_reports_that_it_never_landed() {
        let f = Fake { working: true, ..Fake::new(true) };
        let r = ask(&f, "designerReact", "q", Duration::from_millis(60), ARCHITECT_PARTICIPANT, BusyPolicy::Wait).unwrap();
        assert_eq!(r.delivery, Action::LeaveWorking, "still working when the budget ended");
        assert!(!r.delivered());
        assert!(r.waited_ms.is_some(), "and it says the time went into waiting");
        assert!(f.delivered.borrow().len() > 1, "it actually polled rather than giving up on the first look");
    }

    #[test]
    fn an_idle_or_stopped_target_never_enters_the_wait_loop() {
        // `--on-busy` is about the BUSY case only. A caller who passes `wait` habitually must not pay
        // a poll interval for a target that was ready all along.
        for (live, expected) in [(true, Action::Inject), (false, Action::StartWith)] {
            let f = Fake::new(live);
            let r = ask(&f, "designerReact", "q", T, ARCHITECT_PARTICIPANT, BusyPolicy::Wait).unwrap();
            assert_eq!(r.delivery, expected);
            assert!(r.waited_ms.is_none(), "nothing was waited for");
            assert_eq!(f.delivered.borrow().len(), 1);
        }
    }

    #[test]
    fn the_busy_policy_parses_exactly_its_three_values_and_says_so_when_it_does_not() {
        assert_eq!(BusyPolicy::parse("leave").unwrap(), BusyPolicy::Leave);
        assert_eq!(BusyPolicy::parse("wait").unwrap(), BusyPolicy::Wait);
        assert_eq!(BusyPolicy::parse("interrupt").unwrap(), BusyPolicy::Interrupt);
        assert_eq!(BusyPolicy::default(), BusyPolicy::Leave, "the default must not disturb work in progress");

        for near in ["queue", "idle", "force", "Wait", ""] {
            let err = BusyPolicy::parse(near).unwrap_err();
            for v in ["leave", "wait", "interrupt"] {
                assert!(err.contains(v), "{near}: the refusal names {v} — {err}");
            }
        }
    }

    #[test]
    fn only_interrupt_reaches_the_app_as_an_interrupt() {
        assert!(BusyPolicy::Interrupt.interrupts());
        assert!(!BusyPolicy::Wait.interrupts());
        assert!(!BusyPolicy::Leave.interrupts());
    }

    #[test]
    fn a_session_cannot_ask_itself() {
        let err = resolve_askable("architect", ARCHITECT_PARTICIPANT).unwrap_err();
        assert!(err.contains("cannot ask itself"), "{err}");
        // And it fails BEFORE anything is delivered.
        let f = Fake::new(true);
        assert!(ask(&f, "architect", "q", T, ARCHITECT_PARTICIPANT, BusyPolicy::Leave).is_err());
        assert!(f.delivered.borrow().is_empty(), "nothing is delivered for a refused ask");
        assert!(f.opened.borrow().is_empty(), "and no loop is opened and stranded");

        // The rule is about IDENTITY, not about the architect: the designer asking the designer is
        // refused for the same reason, and the message says so without naming a tier.
        let err = resolve_askable("designerReact", "designerReact").unwrap_err();
        assert!(err.contains("cannot ask itself"), "{err}");
    }

    /// THE regression. A director running `bsc session ask architect …` was refused with "it is the
    /// caller of this verb" — a true statement about the architect and a false one about the
    /// director doing the asking.
    #[test]
    fn a_director_can_ask_the_architect() {
        const DIRECTOR: &str = "network-monitor:director";
        resolve_askable("architect", DIRECTOR).expect("a director may ask the architect");
        let f = Fake::new(true);
        let r = ask(&f, "architect", "we hold no authority", T, DIRECTOR, BusyPolicy::Leave).unwrap();
        assert!(r.delivered());
    }

    /// EVERY system session stays askable. The queue rewrite this replaces narrowed the target set to
    /// director/architect on the evidence that `architect` was the only target named in any protocol —
    /// true of the docs, and false of the usage: of 23 real asks, 16 went to `designerReact` and 4 to
    /// `librarianTypescript`. Narrowing here would refuse 20 of 23.
    #[test]
    fn every_system_session_is_a_valid_target() {
        // The PROJECTION over a representative axis, not a static table — the studio set is derived
        // now. The technologies here are the ones the stores actually hold (MEASURED 2026-09-09), so
        // this asserts askability over exactly the sessions that exist.
        let axis = |kind: &str| match kind {
            "librarian" => vec!["rust".to_string(), "typescript".to_string()],
            "designer" => vec!["react".to_string(), "react-native".to_string()],
            _ => vec![],
        };
        let sessions = crate::studio_sessions(axis);
        assert!(sessions.len() >= 7, "the projection must produce every studio: {sessions:?}");
        for s in &sessions {
            resolve_askable(&s.id, "network-monitor:director")
                .unwrap_or_else(|e| panic!("{} must be askable: {e}", s.id));
        }
    }

    #[test]
    fn the_callers_name_is_its_pane_unless_it_is_a_system_session() {
        // Serialized against the other env-touching test in this module. nextest runs each test in
        // its OWN PROCESS, so this is belt-and-braces — but `cargo test` threads them in one.
        static ENV: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _g = ENV.lock().unwrap_or_else(|e| e.into_inner());

        std::env::remove_var("BSC_AUDIT_PANE");
        assert_eq!(caller_participant(), ARCHITECT_PARTICIPANT, "a bare CLI run is the old behaviour");

        std::env::set_var("BSC_AUDIT_PANE", "teams-studio:architect");
        assert_eq!(caller_participant(), "architect", "the architect keeps its short id");

        std::env::set_var("BSC_AUDIT_PANE", "network-monitor:director");
        assert_eq!(caller_participant(), "network-monitor:director", "anything else uses its pane");

        std::env::remove_var("BSC_AUDIT_PANE");
    }

    /// A REPLY FAKE: participants and a posted turn, with every delivery recorded.
    struct RFake {
        a: String,
        b: String,
        closed: Option<String>,
        said: RefCell<Vec<(i64, String, String)>>,
        delivered: RefCell<Vec<(String, String)>>,
    }
    impl RFake {
        fn new(a: &str, b: &str) -> Self {
            Self { a: a.into(), b: b.into(), closed: None,
                   said: RefCell::new(vec![]), delivered: RefCell::new(vec![]) }
        }
    }
    impl ReplyEnv for RFake {
        fn participants(&self, _l: i64) -> Result<(String, String), String> {
            Ok((self.a.clone(), self.b.clone()))
        }
        fn say(&self, l: i64, speaker: &str, text: &str) -> Result<Posted, String> {
            self.said.borrow_mut().push((l, speaker.into(), text.into()));
            Ok(Posted { seq: self.said.borrow().len() as i64, closed: self.closed.clone() })
        }
        fn deliver(&self, s: &str, text: &str) -> Result<Action, String> {
            self.delivered.borrow_mut().push((s.into(), text.into()));
            Ok(Action::Inject)
        }
    }

    /// THE CYCLE. A studio pauses to ask; the question is posted AND pushed to whoever asked, so it
    /// reaches someone instead of sitting in a store nobody reads. This is the whole reason the loop
    /// came back.
    #[test]
    fn a_studios_question_is_posted_and_delivered_to_the_caller() {
        let f = RFake::new("designerReact", "architect");
        let r = reply(&f, 42, "  which kit — base or mobile?  ", "designerReact").unwrap();

        assert_eq!(f.said.borrow()[0], (42, "designerReact".into(), "which kit — base or mobile?".into()),
            "posted verbatim, trimmed");
        assert_eq!(r.delivered_to.as_deref(), Some("architect"), "…and pushed to the OTHER side");
        assert_eq!(r.delivery, Some(Action::Inject));
        let (_, text) = f.delivered.borrow()[0].clone();
        assert!(text.contains("which kit"), "the message travels: {text}");
        assert!(text.contains("from designerReact"), "…with who sent it: {text}");
        assert!(text.contains("bsc session reply 42"), "…and how to answer: {text}");
    }

    /// The answer travels the other way with no special case — the verb is symmetric, which is what
    /// makes it a cycle rather than two one-way channels.
    #[test]
    fn the_answer_travels_back_the_same_way() {
        let f = RFake::new("designerReact", "architect");
        let r = reply(&f, 42, "use the base kit", "architect").unwrap();
        assert_eq!(r.delivered_to.as_deref(), Some("designerReact"));
    }

    /// A participant this verb cannot reach is a REPORTED no-op, never an error. The overnight designer
    /// pump's other side is `driver` — the app — and failing there would make every turn of a working
    /// feature an error.
    #[test]
    fn a_participant_that_is_not_a_session_is_a_reported_no_op() {
        let f = RFake::new("designer", "driver");
        let r = reply(&f, 7, "changed the accent token", "designer").unwrap();
        assert_eq!(f.said.borrow().len(), 1, "the turn is still POSTED — it is durable either way");
        assert!(r.delivered_to.is_none(), "and the caller is told nothing was pushed");
        assert!(r.delivery.is_none());
        assert!(f.delivered.borrow().is_empty());
    }

    /// A turn from outside the exchange is refused BEFORE it is posted — otherwise the loop carries a
    /// turn with nobody to deliver it to, and the store's alternation is corrupted by a stranger.
    #[test]
    fn a_speaker_outside_the_loop_is_refused_before_anything_is_posted() {
        let f = RFake::new("designerReact", "architect");
        let err = reply(&f, 42, "hello", "librarianRust").unwrap_err();
        assert!(err.contains("not a participant"), "{err}");
        assert!(err.contains("designerReact") && err.contains("architect"), "it names the two: {err}");
        assert!(f.said.borrow().is_empty(), "nothing was posted");
        assert!(f.delivered.borrow().is_empty());
    }

    /// A turn that CLOSED the loop says so to its recipient. Told only the text, they would answer into
    /// a loop that can no longer take a turn and be refused for a reason they could not have known.
    #[test]
    fn a_closing_turn_tells_its_recipient_the_exchange_is_over() {
        let f = RFake { closed: Some("signal".into()), ..RFake::new("designerReact", "architect") };
        let r = reply(&f, 42, "here is the kit ANSWERED", "designerReact").unwrap();
        assert_eq!(r.closed.as_deref(), Some("signal"));
        let (_, text) = f.delivered.borrow()[0].clone();
        assert!(text.contains("CLOSED"), "the recipient is told: {text}");
        assert!(!text.contains("bsc session reply"), "…and NOT invited to answer: {text}");
    }

    #[test]
    fn an_empty_reply_is_refused_before_anything_is_posted() {
        let f = RFake::new("designerReact", "architect");
        assert!(reply(&f, 42, "   ", "designerReact").is_err());
        assert!(f.said.borrow().is_empty());
    }

    #[test]
    fn the_closed_set_still_applies() {
        for candidate in ["studio-code:director", "director", "worker", "Designer"] {
            assert!(resolve_askable(candidate, ARCHITECT_PARTICIPANT).unwrap_err().contains("is not a system session"));
        }
    }

    #[test]
    fn an_empty_request_is_refused_before_anything_is_delivered() {
        let f = Fake::new(true);
        assert!(ask(&f, "designerReact", "   ", T, ARCHITECT_PARTICIPANT, BusyPolicy::Leave).is_err());
        assert!(f.delivered.borrow().is_empty());
    }
}

